+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/** Immutable backend filter shared by page and count queries. */
+public record CustomerFilter(List<String> terms, Set<CustomerStatus> statuses) {
+    public static final CustomerFilter EMPTY = of("", Set.of());
+
+    public CustomerFilter {
+        terms = List.copyOf(terms);
+        statuses = Set.copyOf(statuses);
+    }
+
+    public static CustomerFilter of(String name, Set<CustomerStatus> statuses) {
+        return new CustomerFilter(Arrays.stream(fold(name).split("(?U)\\s+"))
+                .filter(term -> !term.isEmpty()).toList(), statuses);
+    }
+
+    public boolean matches(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private static String fold(String text) {
+        return Normalizer.normalize(text, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
+    }
+}
